// Typed access layer over the key/value `Setting` store (db.setting).
//
// Plain (non-"use server") module so it can export the SETTINGS_DEFAULTS map,
// types and pure helpers alongside the async DB getters/setters. Import it from
// server components, server actions and the worker. Do NOT import from client
// components.
//
// Every admin-editable knob lives here with a default, so reads are total: a key
// that has never been written falls back to its SETTINGS_DEFAULTS value. Booleans
// are stored as the strings "true"/"false"; money is stored in cents; percents as
// plain numbers (e.g. "8.5" = 8.5%).

import { db } from "./db";

export const SETTINGS_DEFAULTS = {
  // --- General / Branding ---
  brand_name: "Nxeon",
  brand_tagline: "Premium VPS hosting, provisioned in seconds.",
  support_email: "",
  company_legal_name: "",
  company_address: "",
  social_twitter: "",
  social_github: "",
  social_discord: "",
  social_linkedin: "",
  footer_text: "",
  // Raw provider <script> body injected by components/marketing/LiveChat.tsx.
  livechat_snippet: "",
  // Business-email DNS guidance shown to customers (MX host + SPF include).
  email_mx_host: "mx.nxeon.email",
  email_spf_include: "_spf.nxeon.email",

  // --- Billing ---
  currency: "USD",
  tax_percent: "0",
  min_topup_cents: "500",
  default_term: "monthly",
  invoice_prefix: "INV-",
  dunning_grace_days: "3",
  dunning_warn_days: "7",
  dunning_terminate_days: "14",
  auto_suspend_enabled: "true",
  // Block storage: price per GB per month (lib/actions-volumes.ts volumePriceCents).
  volume_price_cents_per_gb: "10",

  // --- Domains ---
  domain_markup_percent: "0",
  whois_privacy_default: "true",

  // --- Dedicated IP ---
  // 0 = included: every server gets a dedicated IPv4 and its cost is folded into
  // the plan price (see prisma/seed.ts), so no separate surcharge is billed.
  dedicated_ip_price_cents: "0",
  dedicated_ip_replenish_threshold: "3",
  dedicated_ip_autoreplenish: "false",

  // --- Provisioning & limits ---
  default_plan_slug: "",
  max_servers_per_user: "10",
  signup_free_credit_cents: "0",
  maintenance_mode: "false",
  maintenance_message: "We're performing scheduled maintenance and will be back shortly.",

  // --- Growth ---
  referral_reward_cents: "500",
  coupons_enabled: "true",

  // --- Email / SMTP --- (keys mirror lib/mailer.ts)
  smtp_host: "",
  smtp_port: "587",
  smtp_user: "",
  smtp_pass: "",
  smtp_from: "",
  smtp_secure: "false",

  // --- Security ---
  enforce_staff_2fa: "false",
  session_length_days: "30",
  login_ratelimit_max: "10",
  // Outbound-abuse detection (worker/abuse.ts): sustained outbound Mbps that
  // raises an alert, and whether to auto-suspend the worst (3×) offenders.
  abuse_outbound_mbps: "200",
  abuse_autosuspend: "false",
  allowed_admin_ips: "",

  // --- Feature flags ---
  feature_game_servers: "true",
  feature_claude_builder: "true",
  feature_domains: "true",
  feature_newsletter: "true",
  feature_referrals: "true",
} as const;

export type SettingKey = keyof typeof SETTINGS_DEFAULTS;

/** Keys whose stored value is a secret — never rendered back to the browser. */
export const SECRET_KEYS: readonly string[] = ["smtp_pass"] as const;

/** True-ish coercion for values stored as "true"/"false"/"on"/"1". */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

/** Read one setting, falling back to an explicit default then SETTINGS_DEFAULTS. */
export async function getSetting(key: SettingKey | string, fallback?: string): Promise<string> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return row.value;
  return fallback ?? SETTINGS_DEFAULTS[key as SettingKey] ?? "";
}

/** Read one setting as a boolean. */
export async function getSettingBool(key: SettingKey | string, fallback = false): Promise<boolean> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return isTrue(row.value);
  const def = SETTINGS_DEFAULTS[key as SettingKey];
  return def !== undefined ? isTrue(def) : fallback;
}

/** Read one setting as an integer (cents, days, counts…). */
export async function getSettingInt(key: SettingKey | string, fallback = 0): Promise<number> {
  const raw = await getSetting(key, String(fallback));
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

/** Upsert one setting. */
export async function setSetting(key: SettingKey | string, value: string): Promise<void> {
  await db.setting.upsert({
    where: { key },
    update: { value },
    create: { key, value },
  });
}

/**
 * Every setting, with defaults merged under any stored overrides. Secret values
 * ARE included — callers that hand this to the client (the settings page) must
 * strip SECRET_KEYS themselves.
 */
export async function getAllSettings(): Promise<Record<string, string>> {
  const rows = await db.setting.findMany();
  const merged: Record<string, string> = { ...SETTINGS_DEFAULTS };
  for (const r of rows) merged[r.key] = r.value;
  return merged;
}

// Shared server-upgrade (RESIZE up) core — used by the wallet flow
// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
// checkout can apply the upgrade immediately. Plain server module (not "use server").
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";

/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
export const MS_PER_AVG_MONTH = 30.44 * 86400_000;

export class ResizeError extends Error {}

type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
}
function loadPlan(planId: string) {
  return db.plan.findUnique({ where: { id: planId } });
}

export type ResizeQuote = {
  server: NonNullable<QuotedServer>;
  newPlan: QuotedPlan;
  prorateCents: number;
};

/**
 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
 * duration (monthly price difference for every remaining month; null expiresAt
 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
 * any guard failure. Does NOT check ownership — callers must do that.
 */
export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
  const server = await loadServer(serverId);
  if (!server) throw new ResizeError("Not found");
  const newPlan = await loadPlan(planId);
  if (!newPlan?.active) throw new ResizeError("Plan not available.");
  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
  if (newPlan.diskGB < server.plan.diskGB) {
    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
  }
  if (newPlan.priceCents < server.plan.priceCents) {
    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");

  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    const now = Date.now();
    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
    const monthlyDelta = newPlan.priceCents - server.plan.priceCents; // plan.priceCents is the monthly price
    prorateCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
  }
  return { server, newPlan, prorateCents };
}

/**
 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
 * unauthenticated confirm route. Throws ResizeError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
 * amount the customer paid into their wallet at checkout so the debit here nets to
 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
 * spend the just-credited funds). The wallet path omits it and debits the quote.
 */
export async function applyResize(opts: {
  serverId: string;
  planId: string;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
  const prorateCents = opts.chargeCents ?? quoted;

  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");

  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -prorateCents,
            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
          },
        });
        // PAID invoice for the proration charge (one per user-initiated resize).
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: server.userId,
            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
            status: "PAID",
            lineItems: [
              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
            ],
          }),
        });
      }
      // Record the amount charged on the job so the worker's RESIZE handler can
      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
      // resize terminally fails — money is committed here, before the job runs.
      await tx.job.create({
        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
      });
      await tx.auditLog.create({
        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
    throw e;
  }
}
=====ACTIONS-SERVER=====
"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { resizeQuote, applyResize, ResizeError } from "./resize";
import { createResizeCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function queueJob(
  serverId: string,
  type:
    | "SNAPSHOT_CREATE"
    | "SNAPSHOT_DELETE"
    | "SNAPSHOT_ROLLBACK"
    | "BACKUP_CREATE"
    | "RESIZE"
    | "PASSWORD_RESET",
  payload?: Record<string, unknown>
): Promise<{ error?: string }> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };
  await db.job.create({ data: { type, serverId, payload: payload as any } });
  return {};
}

// ---------- Snapshots ----------

export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${name}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${name}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

// ---------- Backups ----------

export async function createBackup(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "BACKUP_CREATE");
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export type BackupJobStatus = {
  id: string;
  type: "BACKUP_CREATE" | "BACKUP_RESTORE";
  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED";
  progress: number;
  step: string | null;
  error: string | null;
  createdAt: string;
};

/**
 * Return the most recent backup/restore job for a server so the UI can render a
 * live progress bar. Ownership-checked. Returns null if the server has never had
 * a backup/restore job. The client decides when to show the bar (in-flight) vs.
 * the completion/failure note.
 */
export async function getBackupJob(serverId: string): Promise<BackupJobStatus | null> {
  const { server } = await ownedServer(serverId);
  const job = await db.job.findFirst({
    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
    orderBy: { createdAt: "desc" },
    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
  });
  if (!job) return null;
  return {
    id: job.id,
    type: job.type as BackupJobStatus["type"],
    status: job.status as BackupJobStatus["status"],
    progress: job.progress,
    step: job.step,
    error: job.error,
    createdAt: job.createdAt.toISOString(),
  };
}

// ---------- Resize ----------

export async function resizeServer(
  serverId: string,
  planId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkoutUrl?: string }> {
  const { user, server } = await ownedServer(serverId);

  // Validate + price the upgrade (ownership already checked above). resizeQuote
  // recomputes the exact prorated charge over the remaining term.
  let quote;
  try {
    quote = await resizeQuote(serverId, planId);
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    throw e;
  }
  const { newPlan, prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
  // the same split (lib/wallet-split.ts) so displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  // Card portion > 0 → charge ONLY the remainder on the card (not the full
  // proration). The confirm route credits the card amount to the wallet and then
  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
  // share and the card the rest — wallet never touched before the card clears.
  if (cardCents > 0) {
    const url = await createResizeCheckout(user, cardCents, {
      serverId,
      planId,
      planName: newPlan.name,
      prorateCents,
    });
    if (!url) {
      return {
        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkoutUrl: url };
  }

  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
  // servers) → apply instantly, debiting the full proration from the wallet.
  try {
    await applyResize({ serverId, planId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- Root password reset ----------

export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reset its password." };
  }
  const res = await queueJob(serverId, "PASSWORD_RESET");
  if (!res.error) {
    await db.auditLog.create({
      data: { userId: user.id, action: "server.password_reset", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    revalidatePath(`/admin/servers/${serverId}`);
  }
  return res;
}

// ---------- Port forwarding (firewall/networking) ----------

import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
const MAX_FORWARDS_PER_SERVER = 10;

export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user, server } = await ownedServer(serverId);
  const parsed = z
    .object({
      guestPort: z.coerce.number().int().min(1).max(65535),
      protocol: z.enum(["tcp", "udp"]),
    })
    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
  if (!parsed.success) return { error: "Invalid port." };

  const count = await db.portForward.count({ where: { serverId } });
  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };

  const used = new Set([
    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
  ]);
  let publicPort = 0;
  for (let p = PF_MIN; p <= PF_MAX; p++) {
    if (!used.has(p)) { publicPort = p; break; }
  }
  if (!publicPort) return { error: "No public ports available." };

  await db.portForward.create({
    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
  });
  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function deletePortForward(serverId: string, forwardId: string) {
  const { user } = await ownedServer(serverId);
  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
}

// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
// checkout can provision immediately. Plain server module (not "use server").
import { z } from "zod";
import type { User } from "@prisma/client";
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { capacityCheck, diskCapacityCheck } from "./capacity";
import { invoiceCreateData } from "./invoices";
import { maybeRewardReferral } from "./actions-growth";
import { currentPromo, promoPriceCents } from "./promotions";

export class OrderError extends Error {}

export const orderSchema = z.object({
  planId: z.string().min(1),
  osTemplateId: z.string().min(1),
  hostname: z
    .string()
    .min(3)
    .max(40)
    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
});

export type OrderIntent = {
  planId: string;
  osTemplateId: string;
  hostname: string;
  nodeId?: string;
  addonMalware?: boolean;
  addonBackup?: boolean;
  addonDocker?: boolean;
  termMonths?: number;
  dedicatedIp?: boolean;
  sshPublicKey?: string;
  sshKeyName?: string;
  free?: boolean;
};

/** Extract a plain OrderIntent from a deploy form. */
export function intentFromFormData(formData: FormData): OrderIntent {
  return {
    planId: String(formData.get("planId") ?? ""),
    osTemplateId: String(formData.get("osTemplateId") ?? ""),
    hostname: String(formData.get("hostname") ?? ""),
    nodeId: String(formData.get("nodeId") ?? "") || undefined,
    addonMalware: formData.get("addon_malware") === "1",
    addonBackup: formData.get("addon_backup") === "1",
    addonDocker: formData.get("addon_docker") === "1",
    termMonths: Number(formData.get("termMonths") ?? 1),
    dedicatedIp: formData.get("dedicatedIp") === "1",
    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
    free: formData.get("free") === "1",
  };
}

/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
async function scheduleNode(planRamMB: number) {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      return { node: n, free: n.capacityRamMB - used };
    }),
  );
  loads.sort((a, b) => b.free - a.free);
  return loads[0].node;
}

/** Validate + price an order without placing it. Throws OrderError on any problem. */
export async function orderQuote(intent: OrderIntent) {
  const parsed = orderSchema.safeParse(intent);
  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
    throw new OrderError(
      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
    );
  }
  const term = vpsTerm(Number(intent.termMonths ?? 1));
  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
  // real renewal price and this discounted value is the real first-term price.
  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
  // (Dedicated IP is billed at full price; the promo only touches the plan.)
  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
  const promo = currentPromo(new Date());
  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
  const chargeCents = planFirstTermCents + ipCents;
  return { plan, os, term, chargeCents, promo, regularPlanCents };
}

/**
 * Place an order: validate, charge the wallet (unless a free admin grant),
 * create the Server + PROVISION job. Returns the new server id. Does NOT
 * redirect. Callers must ensure funds exist (or pass free) — this still
 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
 */
export async function placeOrder(user: User, intent: OrderIntent): Promise<string> {
  const { plan, os, term, chargeCents, promo } = await orderQuote(intent);
  // Note the intro discount on the billing document (first term only; renews full).
  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";

  const cap = await capacityCheck(plan.id);
  if (!cap.ok) throw new OrderError(cap.reason);

  let nodeId: string | null = null;
  if (intent.nodeId) {
    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
    if (!n) throw new OrderError("Selected location is not available.");
    nodeId = n.id;
  } else {
    const n = await scheduleNode(plan.ramMB);
    nodeId = n?.id ?? null;
  }

  const diskCap = await diskCapacityCheck(nodeId, plan.diskGB);
  if (!diskCap.ok) throw new OrderError(diskCap.reason);

  const addons = {
    malwareScanner: !!intent.addonMalware,
    dailyBackup: !!intent.addonBackup,
    docker: !!intent.addonDocker,
  };
  const isAdmin = user.role === "ADMIN";
  const freeRequested = !!intent.free && isAdmin;
  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");

  const newKey = (intent.sshPublicKey ?? "").trim();
  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);

  let server;
  try {
    server = await db.$transaction(async (tx) => {
      if (!freeRequested) {
        await debitWallet(tx, user.id, chargeCents);
        await tx.walletTransaction.create({
          data: {
            userId: user.id,
            amountCents: -chargeCents,
            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
          },
        });
        // Billing document for the charge — created inside the same debit tx so it
        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: user.id,
            description: lineDesc,
            status: "PAID",
            period: { start: new Date(), end: addMonths(new Date(), term.months) },
            lineItems: [{ description: lineDesc, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
          }),
        });
      }
      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
      }
      const s = await tx.server.create({
        data: {
          name: intent.hostname,
          hostname: intent.hostname,
          userId: user.id,
          planId: plan.id,
          osTemplateId: os.id,
          nodeId,
          addons,
          termMonths: term.months,
          wantsDedicatedIp: !!intent.dedicatedIp,
          isFree: freeRequested,
          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
        },
      });
      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
      return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.order",
      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`,
    },
  });
  if (!freeRequested) {
    try {
      await maybeRewardReferral(user.id);
    } catch {
      /* non-fatal */
    }
  }
  return server.id;
}
=====SSH-EXEC=====
/**
 * Shared, injection-safe SSH execution foundation for the customer control
 * panel (websites, databases, one-click apps, cron & services).
 *
 * This is a plain server-side module (NO "use server", no client imports) so it
 * can be used by both the inline read helpers (lib/cpanel-inline.ts) and the
 * worker executors (worker/websites|databases|apps|services.ts). It NEVER runs
 * in the browser — the customer's root credentials stay on the server.
 *
 * It mirrors the hardening in worker/migrate-real.ts on two axes:
 *
 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that will be
 *      interpolated into a remote command MUST match a shell-inert allowlist
 *      (regexes below contain no quotes/spaces/metacharacters/newlines) or the
 *      operation FAILS. We reject — never sanitize. Callers validate up front
 *      with the `assert*` helpers so a bad value can never reach a shell.
 *
 *   2. SECRETS NEVER TOUCH A COMMAND STRING. Generated DB / app passwords are
 *      written to the far side via a command's STDIN (`execInput`) or an SFTP
 *      file — never as an argv token. Command strings reference only file paths
 *      or values that passed the allowlist.
 *
 * Connection target + root password derivation is identical to lib/sftp.ts and
 * worker/ssl.ts (dedicated IP → own IP:22, else PUBLIC_IP:sshPort; user root).
 */
import { Client, type ClientChannel } from "ssh2";
import { randomBytes } from "node:crypto";
import { connectionTarget, serverRootPassword, type SftpServer } from "./sftp";

// ---- Timeouts -------------------------------------------------------------
export const SSH_CONNECT_TIMEOUT_MS = 15_000;
/** Quick inline reads (list/status/snapshot) — kept short so a slow box can't
 *  wedge a page render. */
export const QUICK_TIMEOUT_MS = 12_000;
/** Small mutating commands (write a vhost, create a DB, edit crontab). */
export const SETUP_TIMEOUT_MS = 60_000;
/** Long installs (php-fpm, an engine, an app download). */
export const INSTALL_TIMEOUT_MS = Number(process.env.CPANEL_INSTALL_TIMEOUT_MS ?? 15 * 60_000);

// ---- Strict allowlist validators (throw on any violation) -----------------
// Every charset below is deliberately shell-inert.
export const DOMAIN_RE =
  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
/** DB / DB-user identifier: letters, digits, underscore. */
export const IDENT_RE = /^[A-Za-z0-9_]{1,32}$/;
/** PHP version like 8.3 / 7.4. */
export const PHP_VERSION_RE = /^\d\.\d$/;
/** systemd unit name (bare service name we control from a fixed list). */
export const SERVICE_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
/** Absolute path with a safe charset, no traversal / double slash. */
export const PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
/** A single crontab time field: digits, * , - , / and commas only. */
export const CRON_FIELD_RE = /^[0-9*,/-]{1,64}$/;
/** App slug from our fixed catalog. */
export const SLUG_RE = /^[a-z][a-z0-9-]{0,31}$/;

export function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}

export function assertDomain(d: string): void {
  assert(typeof d === "string" && DOMAIN_RE.test(d), `Unsupported domain: ${d}`);
}
export function assertIdent(v: string, what: string): void {
  assert(typeof v === "string" && IDENT_RE.test(v), `Unsupported ${what}: ${v}`);
}
export function assertPhp(v: string): void {
  assert(typeof v === "string" && PHP_VERSION_RE.test(v), `Unsupported PHP version: ${v}`);
}
export function assertService(v: string): void {
  assert(typeof v === "string" && SERVICE_RE.test(v), `Unsupported service: ${v}`);
}
export function assertPath(p: string): void {
  assert(
    typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//"),
    `Unsupported path: ${p}`
  );
}
export function assertSlug(s: string): void {
  assert(typeof s === "string" && SLUG_RE.test(s), `Unsupported app: ${s}`);
}

/**
 * Validate a 5-field cron schedule. Each field must match CRON_FIELD_RE, so the
 * whole expression is shell-inert (no metacharacters). Returns the normalized
 * single-spaced expression, or throws.
 */
export function assertCronSchedule(schedule: string): string {
  assert(typeof schedule === "string", "Invalid schedule.");
  const fields = schedule.trim().split(/\s+/);
  assert(fields.length === 5, "A cron schedule must have exactly 5 fields (min hour dom mon dow).");
  for (const f of fields) assert(CRON_FIELD_RE.test(f), `Unsupported cron field: ${f}`);
  return fields.join(" ");
}

/**
 * Defensive POSIX single-quote. Even allowlisted values are quoted when they are
 * interpolated, so a value that (against expectation) slipped through has no
 * shell effect. NEVER used for secrets — those go through STDIN/SFTP.
 */
export function shellQuote(s: string): string {
  return `'${String(s).replace(/'/g, `'\\''`)}'`;
}

// ---- SSH plumbing ---------------------------------------------------------

export type SshResult = { code: number | null; stdout: string; stderr: string };

/**
 * Run one command on an already-connected client, capturing output + exit code.
 * Rejects if the command exceeds `timeoutMs` (the channel is torn down so a hung
 * remote command can't wedge the worker/page).
 */
export function exec(conn: Client, command: string, timeoutMs: number): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/**
 * Run a command and stream `input` into its STDIN — used to write a secret into
 * a file on the far side (`cat > file`) without the secret ever appearing as a
 * command-line argument. Mirrors worker/migrate-real.ts execRemoteInput.
 */
export function execInput(
  conn: Client,
  command: string,
  input: string,
  timeoutMs: number
): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
      stream.end(input);
    });
  });
}

/**
 * Open an SSH connection to a server, run `fn`, and ALWAYS end the connection.
 * Host/port/root-password derived exactly like lib/sftp. Throws a clear error if
 * the server isn't reachable yet or has no root password on record.
 *
 * Callers MUST guard SANDBOX before reaching here — no real SSH in staging.
 */
export async function withServerSsh<T>(
  server: SftpServer,
  fn: (conn: Client) => Promise<T>
): Promise<T> {
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const password = serverRootPassword(server);
  if (!password) throw new Error("Server has no root password on record.");

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => {
      try {
        conn.end();
      } catch {
        /* best effort */
      }
      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
    }, SSH_CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => {
        clearTimeout(timer);
        resolve();
      })
      .on("error", (e) => {
        clearTimeout(timer);
        reject(e instanceof Error ? e : new Error(String(e)));
      })
      .connect({
        host: target.host,
        port: target.port,
        username: "root",
        password,
        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
      });
  });
  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

/**
 * Detect the package manager on the far side and return the install prefix, or
 * throw if none is supported. Fixed strings only — no user input.
 */
export async function pkgInstallPrefix(conn: Client): Promise<string> {
  const pm = await exec(
    conn,
    "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
      "elif command -v dnf >/dev/null 2>&1; then echo dnf; " +
      "elif command -v yum >/dev/null 2>&1; then echo yum; else echo none; fi",
    QUICK_TIMEOUT_MS
  );
  const which = pm.stdout.trim();
  if (which === "apt") return "DEBIAN_FRONTEND=noninteractive apt-get install -y";
  if (which === "dnf") return "dnf install -y";
  if (which === "yum") return "yum install -y";
  throw new Error("No supported package manager (apt-get/dnf/yum) found on the server.");
}

/** A URL-safe generated password (no shell metacharacters, no ambiguity). */
export function generateStrongPassword(len = 20): string {
  return randomBytes(len * 2)
    .toString("base64url")
    .replace(/[-_]/g, "")
    .slice(0, len);
}

