const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";

async function provision(job: Job) {
  const server = await loadServer(job);
  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });

  if (SANDBOX) {
    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
    const vmid = server.vmid ?? (990000 + (await db.server.count()));
    const password = generatePassword();
    const ip = sandboxIp(vmid);
    await db.server.update({
      where: { id: server.id },
      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
    });

