  const snippet = buildCloudInit(server);
  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
    console.error("[worker] snippet write failed", e)
  );

  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
  const sshkeys = keys.length
