    : undefined;
  const cfg: Record<string, any> = {
    cores: server.plan.cpuCores,
    memory: server.plan.ramMB,
    ciuser: "root",
    cipassword: password,
    sshkeys,
    nameserver: "1.1.1.1 8.8.8.8",
    onboot: 1,
    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
  };
  if (dedicated) {
    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
