/**
 * Reverse a money side-effect that a job committed up-front but never delivered.
 * Server actions charge/credit the wallet before enqueuing the worker job (so the
 * UI reflects the change immediately); if the job then fails terminally the money
 * must be unwound or the customer is charged for a resize that never happened
 * (up) or keeps a downgrade credit for hardware they still have (down).
 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
 * double-reverse.
 */
async function reconcileFailedJob(job: Job) {
  if (job.type !== "RESIZE") return;
  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
  const cents = p.prorateCents ?? 0;
  if (cents <= 0 || !job.serverId) return;

  // Idempotency: skip if we already reversed this exact job.
  const already = await db.auditLog.findFirst({
    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
  });
  if (already) return;

  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
  if (!server) return;

  try {
    if (p.direction === "up") {
      // Upgrade charge never delivered → refund the prorated charge.
      await db.$transaction([
        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
        db.walletTransaction.create({
          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
        }),
      ]);
    } else if (p.direction === "down") {
      // Downgrade credit was given but hardware unchanged → claw the credit back.
      // Guarded so it can never drive the balance negative; if the customer already
      // spent it, we log and leave it (best-effort — they keep a small windfall).
      await db.$transaction(async (tx) => {
        await debitWallet(tx, server.userId, cents);
        await tx.walletTransaction.create({
          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
        });
      });
    }
    await db.auditLog.create({
      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
    });
  } catch (e: any) {
    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
    await db.auditLog.create({
      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
    }).catch(() => {});
  }
}

async function runJob(job: Job) {
  // The job is already atomically claimed (status RUNNING, attempts incremented)
  // by the loop's compare-and-swap before we get here — see the CAS in main().
  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
  try {
    await handlers[job.type](job);
    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
    console.log(`[worker] job ${job.id} DONE`);
  } catch (e: any) {
    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
    // leak the server's root password into the thrown message. Redact it before
    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
    // sever the match. Best-effort — never let redaction lookup fail the job path.
    if (job.serverId) {
      try {
        const s = await db.server.findUnique({
          where: { id: job.serverId },
          select: { rootPassword: true, rootPasswordEnc: true },
        });
        const pw = s ? serverRootPassword(s) : null;
        if (pw) error = error.split(pw).join("***");
      } catch {
        /* best-effort redaction */
      }
    }
    error = error.slice(0, 2000);
    console.error(`[worker] job ${job.id} FAILED: ${error}`);
    const current = await db.job.findUnique({ where: { id: job.id } });
    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error },
    });
    if (!retriable) {
      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
      if (job.serverId) {
        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
        if (stillExists) {
          // Only jobs that actually change the VM's run/disk state should strand the
          // server in ERROR. Side operations — backup, snapshot-create, the control-
          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
          // never touch the VM's run state; their failures surface via the executor's
          // own notification and must NOT flip the whole server to ERROR (a failed
          // backup was wrongly making the server look like it had shut down).
          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
            await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
          }
          // A terminally-failed PROVISION must not leak its allocated dedicated IP:
          // release it back to the pool (deletes the billable OVH Virtual MAC) and
          // clear the (UNIQUE) ipAddress so the next server can claim it.
          if (job.type === "PROVISION" && !SANDBOX) {
            await releaseDedicatedIp(job.serverId).catch((err) =>
              console.error(`[worker] release dedicated IP on failed provision ${job.id}`, err)
            );
            await db.server
              .update({ where: { id: job.serverId }, data: { ipAddress: null } })
              .catch(() => {});
          }
        }
      }
    }
  }
}

/**
 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
 * killed worker leaves a job RUNNING forever, which permanently blocks the
 * server's "one in-flight job" guard and strands it in a transitional state.
 */
async function reapStuckJobs() {
  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
  for (const job of stuck) {
    const retriable = job.attempts < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
    });
    if (!retriable) {
      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
      if (job.serverId) {
        const s = await db.server.findUnique({ where: { id: job.serverId } });
        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
        }
      }

import Stripe from "stripe";
import { db } from "./db";
import type { OrderIntent } from "./order";
import { invoiceCreateData } from "./invoices";

export function stripeConfigured(): boolean {
  return !!process.env.STRIPE_SECRET_KEY;
}

let client: Stripe | null = null;

export function stripe(): Stripe {
  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
  return client;
}

/** Create a Checkout session that pays for a VPS order directly (no wallet pre-fund). */
export async function createOrderCheckout(
  user: { id: string; email: string },
  amountCents: number,
  intent: OrderIntent,
): Promise<string | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
          unit_amount: amountCents,
        },
        quantity: 1,
      },
    ],
    metadata: { nxeonUserId: user.id, nxeonOrder: JSON.stringify(slim).slice(0, 490) },
    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${base}/dashboard/deploy?canceled=1`,
  });
  return session.url;
}

/**
 * Create a Checkout session that pays for a prorated server UPGRADE directly (no
 * wallet pre-fund), applying the customer's wallet balance to the split. The CARD
 * is charged only `cardCents` (the remainder after wallet credit); the FULL
 * proration is recorded in metadata as `chargeCents` so the confirm route debits
 * the whole proration back out of the wallet. Since creditCheckoutSession credited
 * only the card portion, the wallet naturally absorbs the difference — the wallet
 * is never touched before the card clears.
 */
export async function createResizeCheckout(
  user: { id: string; email: string },
  cardCents: number,
  resize: { serverId: string; planId: string; planName?: string; prorateCents: number },
): Promise<string | null> {
  if (!stripeConfigured() || cardCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `Nxeon VPS upgrade${resize.planName ? ` — ${resize.planName}` : ""}` },
          unit_amount: cardCents,
        },
        quantity: 1,
      },
    ],
    metadata: {
      nxeonUserId: user.id,
      // chargeCents = the FULL proration to debit on confirm (not the card amount).
      nxeonResize: JSON.stringify({ serverId: resize.serverId, planId: resize.planId, chargeCents: resize.prorateCents }).slice(0, 490),
    },
    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${base}/dashboard/servers/${resize.serverId}?canceled=1`,
  });
  return session.url;
}

/** For the confirm route: the resize intent attached to a paid session, if any. */
export async function getCheckoutResizeIntent(
  sessionId: string,
): Promise<{ userId: string; serverId: string; planId: string; chargeCents: number } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonResize;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    const parsed = JSON.parse(raw) as { serverId: string; planId: string; chargeCents: number };
    return { userId, serverId: parsed.serverId, planId: parsed.planId, chargeCents: parsed.chargeCents };
  } catch {
    return null;
  }
}

/** For the confirm route: the order intent attached to a paid session, if any. */
export async function getCheckoutOrderIntent(
  sessionId: string,
): Promise<{ userId: string; intent: OrderIntent } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonOrder;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    return { userId, intent: JSON.parse(raw) as OrderIntent };
  } catch {
    return null;
  }
}

/**
 * Credit a user's wallet for a completed Checkout session, idempotently.
 * Called from both the success-redirect confirm route (works without HTTPS)
 * and the webhook (belt-and-suspenders once HTTPS is available).
 * Returns true if a credit was applied this call.
 */
export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
  const session = await stripe().checkout.sessions.retrieve(sessionId);
  const userId = session.metadata?.nxeonUserId;
  const cents = session.amount_total ?? 0;
  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;

  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
  // session id inside the description.
  const legacy = await db.walletTransaction.findFirst({
    where: { stripeSessionId: null, description: { contains: session.id } },
  });
  if (legacy) return false;

  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
  // read-then-write check. The confirm-redirect and the webhook can arrive
  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
  // only the database can safely decide the winner. P2002 == already credited.
  try {
    await db.$transaction([
      db.walletTransaction.create({
        data: {
          userId,
          amountCents: cents,
          description: `Stripe payment (${session.id})`,
          stripeSessionId: session.id,
        },
      }),
      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
      db.notification.create({
        data: {
          userId,
          title: `Payment of $${(cents / 100).toFixed(2)} received`,
          href: "/dashboard/billing",
        },
      }),
      // PAID invoice for the top-up. Created in the SAME guarded transaction as
      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
      // the credit idempotent also prevents a duplicate invoice on replay.
      db.invoice.create({
        data: invoiceCreateData({
          userId,
          description: "Wallet top-up",
          status: "PAID",
          lineItems: [
            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
          ],
        }),
      }),
    ]);
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
    throw e;
  }
  // A funded wallet is the referred user's first paid action — reward both sides.
  try {
    const { maybeRewardReferral } = await import("./actions-growth");
    await maybeRewardReferral(userId);
  } catch { /* best-effort */ }
  try {
    const u = await db.user.findUnique({ where: { id: userId } });
    if (u) {
      const { sendMail, emails } = await import("./mailer");
      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
    }
  } catch { /* best-effort */ }
  return true;
}

import { NextRequest, NextResponse } from "next/server";
import {
  creditCheckoutSession,
  getCheckoutOrderIntent,
  getCheckoutResizeIntent,
  stripeConfigured,
} from "@/lib/stripe";
import { db } from "@/lib/db";
import { placeOrder } from "@/lib/order";
import { applyResize } from "@/lib/resize";

/**
 * Checkout success redirect target. Verifies the session server-side and credits
 * the wallet immediately — no webhook (and therefore no HTTPS) required. When the
 * session carries a direct-pay order intent, the server is provisioned right away
 * (once — guarded by the idempotent credit).
 */
export async function GET(req: NextRequest) {
  const base = process.env.APP_URL ?? "";
  const sessionId = req.nextUrl.searchParams.get("session_id");
  if (!stripeConfigured() || !sessionId) {
    return NextResponse.redirect(`${base}/dashboard/billing`);
  }
  try {
    const credited = await creditCheckoutSession(sessionId);
    const order = await getCheckoutOrderIntent(sessionId);
    if (order) {
      // `credited` is true only on the first successful credit for this session,
      // so provisioning runs exactly once even if the confirm URL is reloaded.
      if (credited) {
        const user = await db.user.findUnique({ where: { id: order.userId } });
        if (user) {
          try {
            const serverId = await placeOrder(user, order.intent);
            return NextResponse.redirect(`${base}/dashboard/servers/${serverId}`);
          } catch {
            // Payment captured but provisioning failed — funds are in the wallet.
            return NextResponse.redirect(`${base}/dashboard/deploy?paid=1`);
          }
        }
      }
      return NextResponse.redirect(`${base}/dashboard/servers`);
    }
    // Paid server upgrade: apply the resize exactly once. `credited` is true only
    // on the first successful credit for this session (guarded by the UNIQUE
    // stripeSessionId), so applyResize runs at most once even if this URL is
    // reloaded — mirrors the deploy path's single-shot provisioning. The card
    // funds were just credited to the wallet; applyResize debits them back out
    // (chargeCents), netting to zero.
    const resize = await getCheckoutResizeIntent(sessionId);
    if (resize) {
      if (credited) {
        try {
          await applyResize({
            serverId: resize.serverId,
            planId: resize.planId,
            actorUserId: resize.userId,
            chargeCents: resize.chargeCents,
          });
          return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}`);
        } catch {
          // Payment captured but the resize couldn't be queued (e.g. server now
          // busy) — funds are in the wallet; surface the paid state.
          return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}?paid=1`);
        }
      }
      return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}`);
    }
    return NextResponse.redirect(`${base}/dashboard/billing?paid=1`);
  } catch {
    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
  }
}

"use client";

import { useState, useTransition } from "react";
import { resizeServer } from "@/lib/actions-server";
import { fmtMoney } from "@/components/ui/primitives";
import { walletSplit } from "@/lib/wallet-split";

/** Average calendar month in ms — mirrors resizeQuote on the server (estimate only). */
const MS_PER_AVG_MONTH = 30.44 * 86400_000;

type PlanRow = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
};

export function ResizePicker({
  serverId,
  currentPlanId,
  currentDiskGB,
  currentPriceCents,
  expiresAt,
  isFree,
  walletBalanceCents,
  plans,
  disabled,
}: {
  serverId: string;
  currentPlanId: string;
  currentDiskGB: number;
  currentPriceCents: number;
  /** ISO string of the current term end, or null (free/admin servers). */
  expiresAt: string | null;
  isFree: boolean;
  walletBalanceCents: number;
  plans: PlanRow[];
  disabled?: boolean;
}) {
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  // Apply the wallet balance by default whenever there's something to apply.
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
  const target = plans.find((p) => p.id === selected);

  // Estimated prorated upgrade charge (mirrors resizeQuote on the server). The
  // server recomputes authoritatively; this only drives the button copy.
  function estimateProrate(newPriceCents: number): number {
    if (isFree || !expiresAt) return 0;
    const remainingMonths = Math.max(0, (new Date(expiresAt).getTime() - Date.now()) / MS_PER_AVG_MONTH);
    const monthlyDelta = newPriceCents - currentPriceCents;
    return Math.max(0, Math.round(monthlyDelta * remainingMonths));
  }

  const prorate = target ? estimateProrate(target.priceCents) : 0;
  // Exact wallet/card split — identical math to lib/actions-server.ts resizeServer,
  // so the numbers shown here are what actually gets charged. (The server recomputes
  // the proration authoritatively; this drives the copy + button.)
  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
  const walletApplied = split.walletApplied;
  const cardCents = split.cardCents;

  return (
    <div className="space-y-5">
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {plans.map((p) => {
          const current = p.id === currentPlanId;
          const tooSmall = p.diskGB < currentDiskGB;
          const active = selected === p.id;
          return (
            <button
              key={p.id}
              type="button"
              disabled={current || tooSmall || pending || disabled}
              title={
                tooSmall
                  ? `Disk can only grow — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
                  : undefined
              }
              onClick={() => setSelected(active ? null : p.id)}
              className={`card p-4 text-left transition-all ${
                current
                  ? "border-brand-400/60 ring-1 ring-brand-400/60"
                  : tooSmall
                    ? "cursor-not-allowed opacity-40"
                    : active
                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
                      : "cursor-pointer hover:border-white/20"
              }`}
            >
              <div className="flex items-baseline justify-between">
                <span className="font-semibold">{p.name}</span>
                <span className="text-lg font-bold">{fmtMoney(p.priceCents)}<span className="text-xs font-normal text-slate-400">/mo</span></span>
              </div>
              <p className="mt-1 text-sm text-slate-400">
                {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe · {p.bandwidthTB} TB
              </p>
              {current && <p className="mt-2 text-xs font-semibold text-brand-300">Current plan</p>}
              {tooSmall && <p className="mt-2 text-xs text-slate-500">Smaller disk — unavailable</p>}
            </button>
          );
        })}
      </div>

      <div className="space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
        {target && prorate > 0 && walletBalanceCents > 0 && (
          <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
            <span className="flex items-center gap-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Apply my balance ({fmtMoney(walletBalanceCents)})
            </span>
            <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
          </label>
        )}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-slate-400">
            {target && prorate > 0 ? (
              <>
                Prorated upgrade charge:{" "}
                <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest of your term
                {walletApplied > 0 && <> — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span> from your wallet</>}
                {cardCents > 0 ? <> and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card checkout</> : <> (nothing due on card)</>}.
                {split.clampedForStripeMin && <> Card payments have a {fmtMoney(50)} minimum, so {fmtMoney(cardCents)} goes on the card.</>}
                {" "}Requires a power cycle.
              </>
            ) : (
              "Resizing requires a power cycle. The new price applies at your next renewal."
            )}
          </p>
          <button
            className="btn-primary"
            disabled={!target || pending || disabled}
            onClick={() => {
              if (!target) return;
              if (
                !window.confirm(
                  `Resize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)? The server will be power-cycled.`
                )
              )
                return;
              start(async () => {
                setError(null);
                const res = await resizeServer(serverId, target.id, useWallet);
                // Card portion > 0 → the action returns a Stripe Checkout URL.
                if (res?.checkoutUrl) {
                  window.location.href = res.checkoutUrl;
                  return;
                }
                if (res?.error) setError(res.error);
                else setSelected(null);
              });
            }}
          >
            {pending
              ? "Resizing…"
              : !target
                ? "Select a plan"
                : cardCents > 0
                  ? `Continue to payment — ${fmtMoney(cardCents)}`
                  : prorate > 0
                    ? `Upgrade to ${target.name} — ${fmtMoney(walletApplied)}`
                    : `Resize to ${target.name}`}
          </button>
        </div>
      </div>
    </div>
  );
}

