import { db } from "../lib/db";
import {
  registrarConfigured,
  renewDomain,
  transfersAvailable,
  getTransfer,
  domainInfo,
  transferOutcome,
  transferStatusLabel,
} from "../lib/registrar";
import {
  TRANSFER_STALE_DAYS,
  TRANSFER_TERM_YEARS,
  settleCompletedTransferIn,
  settleFailedTransferIn,
} from "../lib/domain-transfer";
import { vpsTerm, vpsTermPriceCents, domainTerm, domainTermPriceCents, addMonths } from "../lib/billing-terms";
import { dedicatedIpMonthlyCents } from "../lib/dedicated-ip";
import { debitWallet, InsufficientBalanceError } from "../lib/wallet";
import { invoiceCreateData } from "../lib/invoices";

/** Thrown when a compare-and-swap shows someone else already advanced the period. */
class AlreadyRenewedError extends Error {}

const GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
const RENEW_DAYS = 30;
const DOMAIN_RENEW_WINDOW_DAYS = 7;
/** Days a server stays SUSPENDED (unpaid) before it is permanently terminated. */
const TERMINATE_DAYS = Number(process.env.NXEON_TERMINATE_DAYS ?? 10);
/** Warn the customer this many days before termination. */
const WARN_BEFORE_TERMINATE_DAYS = Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS ?? 2);
const DAY = 86400_000;

/**
 * Subscription sweep, run periodically by the worker:
 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
 * Free servers (isFree) are never touched.
 */
export async function billingSweep() {
  const now = new Date();
  const ipMonthly = await dedicatedIpMonthlyCents(); // admin setting; 0 = included

  // Renewal warnings: notify once when a paid server is within 3 days of expiry
  const soon = new Date(now.getTime() + 3 * 86400_000);
  const upcoming = await db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { gt: now, lt: soon },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });
  for (const server of upcoming) {
    const warnCents = server.gamePlan
      ? server.gamePlan.priceCents
      : vpsTermPriceCents(server.plan.priceCents, server.termMonths) +
        (server.dedicatedIp ? ipMonthly * server.termMonths : 0);
    if (server.autoRenew && server.user.balanceCents >= warnCents) continue;
    const already = await db.notification.findFirst({
      where: {
        userId: server.userId,
        title: { contains: server.hostname },
        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
        AND: { title: { contains: "renews soon" } },
      },
    });
    if (!already) {
      await db.notification.create({
        data: {
          userId: server.userId,
          title: `${server.hostname} renews soon — action needed`,
          body: server.autoRenew
            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
          href: `/dashboard/servers/${server.id}`,
        },
      });
    }
  }
  const due = await db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { lt: now },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });

  for (const server of due) {
    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
    const renewTerm = vpsTerm(server.termMonths);
    const isGame = !!server.gamePlan;
    const renewMonths = isGame ? server.gamePlan!.termMonths : renewTerm.months;
    const renewCents = isGame
      ? server.gamePlan!.priceCents
      : vpsTermPriceCents(server.plan.priceCents, renewTerm.months) +
        // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP
        // (the DedicatedIp row is the source of truth), not off the intent flag —
        // otherwise a NAT-fallback server is charged forever for an IP it never got.
        (server.dedicatedIp ? ipMonthly * renewTerm.months : 0);

    // NOTE: `server.user.balanceCents` came from a snapshot taken before this loop,
    // so it is stale as soon as the first renewal in this pass debits the wallet.
    // Never gate the charge on it — `debitWallet` re-checks funds atomically, and a
    // compare-and-swap on `expiresAt` stops a concurrent renewNow()/second pass from
    // charging the same period twice.
    let renewed = false;
    if (server.autoRenew) {
      const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
      const newExpiry = addMonths(base, renewMonths);
      try {
        await db.$transaction(async (tx) => {
          const advanced = await tx.server.updateMany({
            where: { id: server.id, expiresAt: server.expiresAt },
            data: { expiresAt: newExpiry },
          });
          if (advanced.count === 0) throw new AlreadyRenewedError();
          await debitWallet(tx, server.userId, renewCents);
          await tx.walletTransaction.create({
            data: {
              userId: server.userId,
              amountCents: -renewCents,
              description: `Renewal: ${isGame ? server.gamePlan!.name : `${server.plan.name} VPS`} (${server.hostname})`,
            },
          });
          // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
          // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
          // never producing a second invoice for the same period.
          const renewLabel = isGame ? server.gamePlan!.name : `${server.plan.name} VPS`;
          await tx.invoice.create({
            data: invoiceCreateData({
              userId: server.userId,
              description: `Renewal: ${renewLabel} (${server.hostname})`,
              status: "PAID",
              period: { start: server.expiresAt, end: newExpiry },
              lineItems: [
                { description: `${renewLabel} — ${server.hostname}`, qty: 1, unitCents: renewCents, amountCents: renewCents },
              ],
            }),
          });
          await tx.auditLog.create({
            data: { userId: server.userId, action: "billing.renewed", detail: server.id },
          });
        });
        renewed = true;
        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
      } catch (e) {
        if (e instanceof InsufficientBalanceError) {
          console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
        } else if (e instanceof AlreadyRenewedError) {
          renewed = true; // someone else advanced the period; nothing owed here
        } else {
          throw e;
        }
      }
    }
    if (renewed) {
      // nothing further this pass
    } else if (now > graceEnd) {
      const pending = await db.job.count({
        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
      });
      if (pending === 0) {
        await db.server.update({
          where: { id: server.id },
          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
        });
        await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
        await db.auditLog.create({
          data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
        });
        await db.notification.create({
          data: {
            userId: server.userId,
            title: `${server.hostname} suspended — payment overdue`,
            body: "Pay from the server page to restore access instantly.",
            href: `/dashboard/servers/${server.id}`,
          },
        });
        console.log(`[billing] suspending unpaid ${server.hostname}`);
      }
    }
  }

  await terminateOverdue(now);

  await domainAutoRenewSweep(now);

  // Poll in-flight inbound transfers on the same cadence as domain renewals —
  // domain upkeep all lives on one timer.
  try {
    await domainTransferInSweep(now);
  } catch (e) {
    console.error("[billing] domain transfer-in sweep error", e);
  }
}

/* ------------------------------------------------------------------ *
 * Inbound domain transfers (transfer-in)
 * ------------------------------------------------------------------ */

/** Remind the customer to approve the confirmation email at most this often. */
const TRANSFER_NUDGE_DAYS = 3;

/**
 * Poll every TRANSFER_PENDING domain and move it to its real state.
 *
 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
 *   pending   -> raw registrar status refreshed for display, gentle nudge
 *
 * Every mutation goes through the shared CAS-guarded settle helpers, so a
 * re-run, two workers racing, or a customer cancelling at the same moment can
 * never credit the same transfer twice.
 */
async function domainTransferInSweep(now: Date) {
  if (!transfersAvailable()) return; // registrar not configured — skip silently

  const pending = await db.domain.findMany({
    where: { status: "TRANSFER_PENDING", isTransferIn: true },
  });

  for (const domain of pending) {
    try {
      const info = await getTransfer(domain.name, domain.transferStartedAt);

      // No transfer on record. Normal once a transfer settles and drops off the
      // registrar's list — resolve it against the account rather than guessing.
      if (!info) {
        const owned = await domainInfo(domain.name).catch(() => null);
        if (owned?.expires) {
          await completeTransferIn(domain, "completed", owned);
          continue;
        }
        const startedAt = domain.transferStartedAt ?? domain.createdAt;
        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
        if (ageDays > TRANSFER_STALE_DAYS) {
          await failTransferIn(
            domain,
            null,
            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
          );
        }
        continue;
      }

      const outcome = transferOutcome(info.status);

      if (outcome === "completed") {
        const owned = await domainInfo(domain.name).catch(() => null);
        await completeTransferIn(domain, info.status, owned);
        continue;
      }

      if (outcome === "failed") {
        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
        continue;
      }

      // Still in flight — keep the displayed registrar status fresh.
      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
        await db.domain.update({
          where: { id: domain.id },
          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
        });
      }
      await nudgeTransferApproval(domain, info.status, info.email, now);
    } catch (e) {
      // One unhappy domain must never abort the sweep. Nothing is settled and
      // no money moves on an unknown state — we simply try again next pass.
      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
    }
  }
}

async function completeTransferIn(
  domain: { id: string; name: string; userId: string },
  rawStatus: string,
  owned: { expires?: Date; created?: Date } | null
) {
  const expiresAt = owned?.expires ?? new Date(Date.now() + TRANSFER_TERM_YEARS * 365 * DAY);
  const settled = await settleCompletedTransferIn({
    domainId: domain.id,
    transferStatus: rawStatus,
    registeredAt: owned?.created ?? new Date(),
    expiresAt,
  });
  if (!settled) return;

  await db.auditLog.create({
    data: { userId: domain.userId, action: "domain.transfer_in.completed", detail: domain.name },
  });
  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transferred in successfully`,
      body: `It's now managed here and expires ${expiresAt.toISOString().slice(0, 10)} — the transfer added a year. DNS and auto-renew are ready to set up.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
  console.log(`[billing] transfer-in completed for ${domain.name}`);
}

async function failTransferIn(
  domain: { id: string; name: string; userId: string; priceCents: number },
  rawStatus: string | null,
  reason: string
) {
  const settled = await settleFailedTransferIn({
    domainId: domain.id,
    transferStatus: rawStatus,
    reason,
  });
  if (!settled) return;

  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transfer did not complete`,
      body: `${reason} We've credited $${(domain.priceCents / 100).toFixed(2)} back to your wallet. The most common cause is the confirmation email from your old registrar not being approved in time — you can start a new transfer whenever you're ready.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
  console.log(`[billing] transfer-in failed for ${domain.name}: ${reason}`);
}

/**
 * Nothing completes until the customer approves the losing registrar's email,
 * and that email is easy to miss. Nudge once every few days while we're waiting
 * — deduped on the notification log, same as the other billing reminders.
 */
async function nudgeTransferApproval(
  domain: { id: string; name: string; userId: string; transferStartedAt: Date | null; createdAt: Date },
  rawStatus: string,
  email: string | null,
  now: Date
) {
  const startedAt = domain.transferStartedAt ?? domain.createdAt;
  if (now.getTime() - startedAt.getTime() < 2 * DAY) return; // give them room first

  const already = await db.notification.findFirst({
    where: {
      userId: domain.userId,
      title: { contains: domain.name },
      AND: { title: { contains: "still waiting" } },
      createdAt: { gt: new Date(now.getTime() - TRANSFER_NUDGE_DAYS * DAY) },
    },
  });
  if (already) return;

  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transfer is still waiting`,
      body:
        `Registrar status: ${transferStatusLabel(rawStatus)}. ` +
        (email ? `Check ${email} ` : "Check the inbox for the domain's registered contact ") +
        `for the confirmation email from your CURRENT registrar and approve it. Transfers normally take 5–7 days and expire if the approval never arrives.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
}

/**
 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
 * A payment before this point unsuspends the server, so this only ever hits
 * genuinely abandoned accounts. Free servers are never terminated.
 */
async function terminateOverdue(now: Date) {
  const suspended = await db.server.findMany({
    where: { isFree: false, status: "SUSPENDED", expiresAt: { not: null } },
  });
  for (const server of suspended) {
    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;

    if (now.getTime() >= terminateAt) {
      const pending = await db.job.count({
        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
      });
      if (pending > 0) continue;
      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
      await db.auditLog.create({
        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
      });
      await db.notification.create({
        data: {
          userId: server.userId,
          title: `${server.hostname} was permanently deleted`,
          body: "Your server and its data were removed after prolonged non-payment.",
        },
      });
      console.log(`[billing] terminating abandoned ${server.hostname}`);
    } else if (now.getTime() >= warnAt) {
      const already = await db.notification.findFirst({
        where: {
          userId: server.userId,
          title: { contains: server.hostname },
          AND: { title: { contains: "will be deleted" } },
          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
        },
      });
      if (!already) {
        await db.notification.create({
          data: {
            userId: server.userId,
            title: `${server.hostname} will be deleted soon`,
            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
            href: `/dashboard/servers/${server.id}`,
          },
        });
      }
    }
  }
}

/**
 * Auto-renew domains expiring within 7 days when the owner opted in and has
 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
 * Failures (registrar error, misconfig) notify the owner to renew manually and
 * never charge the wallet.
 */
async function domainAutoRenewSweep(now: Date) {
  if (!registrarConfigured()) return; // registrar not configured — skip silently

  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
  const domains = await db.domain.findMany({
    where: {
      autoRenew: true,
      status: "ACTIVE",
      expiresAt: { not: null, lt: cutoff },
    },
    include: { user: true },
  });

  for (const domain of domains) {
    if (!domain.expiresAt) continue;
    const dTerm = domainTerm(domain.termYears);
    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
    if (domain.user.balanceCents < dRenewCents) {
      const already = await db.notification.findFirst({
        where: {
          userId: domain.userId,
          title: { contains: domain.name },
          AND: { title: { contains: "auto-renew failed" } },
          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
        },
      });
      if (!already) {
        await db.notification.create({
          data: {
            userId: domain.userId,
            title: `${domain.name} auto-renew failed — top up to renew`,
            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
            href: `/dashboard/domains`,
          },
        });
      }
      continue;
    }

    try {
      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
    } catch (e) {
      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
      await db.notification.create({
        data: {
          userId: domain.userId,
          title: `${domain.name} auto-renew failed — please renew manually`,
          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
          href: `/dashboard/domains`,
        },
      });
      continue;
    }

    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
    // The registrar renewal already succeeded above, so the cost is committed.
    // Charge with the guarded debit (the loop's snapshot balance is stale), and
    // CAS the expiry so a concurrent manual renew can't be charged twice. If the
    // wallet can't cover it we must STILL record the renewal we paid for — flag it
    // as uncharged for ops rather than silently eating it or renewing twice later.
    try {
      await db.$transaction(async (tx) => {
        const advanced = await tx.domain.updateMany({
          where: { id: domain.id, expiresAt: domain.expiresAt },
          data: { expiresAt: newExpiry },
        });
        if (advanced.count === 0) throw new AlreadyRenewedError();
        await debitWallet(tx, domain.userId, dRenewCents);
        await tx.walletTransaction.create({
          data: {
            userId: domain.userId,
            amountCents: -dRenewCents,
            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
          },
        });
        // PAID invoice on the successfully-charged path only (the uncharged
        // InsufficientBalance branch below deliberately makes no invoice). Inside
        // the CAS-guarded tx, so a repeated sweep rolls it back with the debit.
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: domain.userId,
            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
            status: "PAID",
            period: { start: domain.expiresAt, end: newExpiry },
            lineItems: [
              { description: `Domain renewal — ${domain.name} (${dTerm.label})`, qty: 1, unitCents: dRenewCents, amountCents: dRenewCents },
            ],
          }),
        });
        await tx.auditLog.create({
          data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
        });
      });
    } catch (e) {
      if (e instanceof AlreadyRenewedError) {
        continue; // someone already advanced this period
      }
      if (e instanceof InsufficientBalanceError) {
        await db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } });
        await db.auditLog.create({
          data: {
            userId: domain.userId,
            action: "domain.renew.uncharged",
            detail: `${domain.name}: renewed at registrar but wallet could not be charged ${dRenewCents}c — collect manually`,
          },
        });
        console.error(`[billing] UNCHARGED domain renewal for ${domain.name} (insufficient balance)`);
        continue;
      }
      throw e;
    }
    await db.notification.create({
      data: {
        userId: domain.userId,
        title: `${domain.name} renewed automatically`,
        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
        href: `/dashboard/domains`,
      },
    });
    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
  }
}

