/**
 * Create a Checkout session that pays for a prorated per-server DISK EXPANSION
 * directly (no wallet pre-fund), applying the customer's wallet balance to the
 * split. Structurally identical to createResizeCheckout: the CARD is charged only
 * `cardCents` (the remainder after wallet credit) while the FULL proration travels
 * in metadata as `chargeCents`, so the confirm route debits the whole proration
 * back out of the wallet against the just-credited card amount. The wallet is
 * never touched before the card clears.
 */
export async function createDiskExpandCheckout(
  user: { id: string; email: string },
  cardCents: number,
  expand: { serverId: string; addGB: number; hostname?: string; prorateCents: number },
): Promise<string | null> {
  if (!stripeConfigured() || cardCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: `Nxeon +${expand.addGB} GB disk${expand.hostname ? ` — ${expand.hostname}` : ""}`,
            // The one-way nature is on the Stripe page itself, not just in our UI.
            description: "Permanent storage expansion — disk space can be added but never removed.",
          },
          unit_amount: cardCents,
        },
        quantity: 1,
      },
    ],
    metadata: {
      nxeonUserId: user.id,
      // chargeCents = the FULL proration to debit on confirm (not the card amount).
      nxeonDiskExpand: JSON.stringify({
        serverId: expand.serverId,
        addGB: expand.addGB,
        chargeCents: expand.prorateCents,
      }).slice(0, 490),
    },
    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${base}/dashboard/servers/${expand.serverId}?canceled=1`,
  });
  return session.url;
}

/** For the confirm route: the disk-expansion intent attached to a paid session, if any. */
export async function getCheckoutDiskExpandIntent(
  sessionId: string,
): Promise<{ userId: string; serverId: string; addGB: number; chargeCents: number } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonDiskExpand;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    const parsed = JSON.parse(raw) as { serverId: string; addGB: number; chargeCents: number };
    return { userId, serverId: parsed.serverId, addGB: parsed.addGB, chargeCents: parsed.chargeCents };
  } catch {
    return null;
  }
}

