cat > /opt/nxeon/worker/disk-expand.ts <<'NXEOF'
import { db } from "../lib/db";
import { pve, node as envNode, waitForTask, nextVmid, vmStatus, pveFor } from "../lib/proxmox";
import { SANDBOX } from "../lib/sandbox";
import {
  withServerSsh,
  exec,
  shellQuote,
  QUICK_TIMEOUT_MS,
  SETUP_TIMEOUT_MS,
} from "../lib/ssh-exec";
import { effectiveDiskGB } from "../lib/extra-disk";
import type { Client } from "ssh2";
import type { Job } from "@prisma/client";

/**
 * Per-server DISK EXPANSION handler (JobType.DISK_EXPAND).
 *
 * Grows ONE server's own root disk by N GB — the plan's CPU/RAM are untouched.
 * Payment already happened at enqueue time (lib/disk-expand.ts applyDiskExpand),
 * so this handler trusts `payload.addGB` / `payload.targetExtraDiskGB` and is
 * responsible only for delivering the space.
 *
 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there
 * as `DISK_EXPAND: diskExpand`. It must NOT be listed in VM_STATE_FAILURE_JOBS:
 * growing a disk never changes the VM's run state, so a failure must not strand
 * the server in ERROR (see the note in worker/index.ts).
 *
 * ─── SEQUENCE ───────────────────────────────────────────────────────────────
 *   1. read the VM config, work out the CURRENT scsi0 size
 *   2. if it is already >= the target, SKIP Proxmox entirely (idempotent retry)
 *      otherwise PUT .../resize with size=+<delta>G  (Proxmox only ever grows)
 *   3. online-grow the guest: rescan the device, growpart the root partition,
 *      then resize2fs / xfs_growfs / btrfs resize depending on the fs type
 *   4. persist Server.extraDiskGB and notify
 *
 * ─── RETRY SAFETY ───────────────────────────────────────────────────────────
 * Every step is idempotent. A retry after a crash mid-way re-reads the real disk
 * size from Proxmox, skips work already done, and re-runs the guest grow (which
 * is a no-op — growpart reports NOCHANGE and resize2fs "nothing to do").
 *
 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 * Proxmox refuses to shrink a disk and so do we: the delta is always positive and
 * `Server.extraDiskGB` is only ever raised.
 *
 * ─── THE CUSTOMER NEVER PAYS FOR INVISIBLE SPACE ────────────────────────────
 * If the guest grow can't be done online (server stopped, unreachable, LVM/exotic
 * layout, missing tools) the disk is STILL bigger — so this is NOT treated as a
 * failure. The job completes and the notification spells out the exact commands
 * to run, rather than leaving the customer paying for space they can't see.
 */

/** Root device paths are the only thing we ever interpolate — keep them inert. */
const DEV_PATH_RE = /^\/dev\/[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$/;
/** A bare kernel block-device name, e.g. "sda", "vda", "nvme0n1". */
const DEV_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/;
/** A partition number, 1–99. */
const PARTNUM_RE = /^[1-9][0-9]?$/;
/** Filesystems we know how to grow online. */
const GROWABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);

/** Best-effort live progress write onto the running Job row (never throws). */
async function reportJobProgress(jobId: string, progress: number, step: string) {
  try {
    await db.job.update({
      where: { id: jobId },
      data: { progress: Math.max(0, Math.min(100, Math.round(progress))), step },
    });
  } catch (e) {
    console.error("[disk-expand] job progress update failed", e);
  }
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[disk-expand] notify failed", e);
  }
}

/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
async function nodeFor(server: any) {
  const n =
    server?.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    return {
      conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node: envNode, waitForTask, nextVmid, vmStatus } as any,
      row: null,
    };
  }
  return {
    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
    row: n,
  };
}

/**
 * Parse the size out of a Proxmox disk config string, e.g.
 * "vmdata:vm-101-disk-0,size=50G" / ",size=32768M" / ",size=1T".
 * Returns GB (floor), or null when the string carries no size.
 */
export function parseDiskSizeGB(spec: string | undefined | null): number | null {
  if (typeof spec !== "string") return null;
  const m = /(?:^|,)size=(\d+(?:\.\d+)?)([KMGT]?)/i.exec(spec);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n)) return null;
  switch ((m[2] || "").toUpperCase()) {
    case "T": return Math.floor(n * 1024);
    case "G": return Math.floor(n);
    case "M": return Math.floor(n / 1024);
    case "K": return Math.floor(n / 1024 / 1024);
    default:  return Math.floor(n / 1024 ** 3); // bare bytes
  }
}

type GuestLayout = {
  rootDevice: string;   // /dev/sda1
  fsType: string;       // ext4 | xfs | …
  parentName: string;   // sda
  partNum: string;      // 1
};

/**
 * Read the guest's root-filesystem layout with a single READ-ONLY command
 * (fixed string — nothing is interpolated), then validate every field against a
 * shell-inert allowlist before it is ever used in a mutating command. We reject
 * rather than sanitize, exactly like lib/ssh-exec.ts.
 */
async function detectLayout(conn: Client): Promise<GuestLayout | { error: string }> {
  const probe = [
    'ROOT="$(findmnt -nro SOURCE / 2>/dev/null | head -n1)"',
    'FSTYPE="$(findmnt -nro FSTYPE / 2>/dev/null | head -n1)"',
    'BASE="$(basename "$ROOT" 2>/dev/null)"',
    'PARENT="$(lsblk -nro PKNAME "$ROOT" 2>/dev/null | head -n1)"',
    'PARTNUM="$(cat "/sys/class/block/$BASE/partition" 2>/dev/null || echo "")"',
    'echo "ROOT=$ROOT"; echo "FSTYPE=$FSTYPE"; echo "PARENT=$PARENT"; echo "PARTNUM=$PARTNUM"',
  ].join("; ");
  const res = await exec(conn, probe, QUICK_TIMEOUT_MS);
  const get = (k: string) =>
    (new RegExp(`^${k}=(.*)$`, "m").exec(res.stdout)?.[1] ?? "").trim();

  const rootDevice = get("ROOT");
  const fsType = get("FSTYPE").toLowerCase();
  const parentName = get("PARENT");
  const partNum = get("PARTNUM");

  if (!DEV_PATH_RE.test(rootDevice)) {
    return { error: `could not identify the root device (got "${rootDevice.slice(0, 40)}")` };
  }
  if (!GROWABLE_FS.has(fsType)) {
    return { error: `unsupported root filesystem "${fsType.slice(0, 20) || "unknown"}"` };
  }
  // LVM / device-mapper roots need pvresize + lvextend, which we will not
  // attempt unattended on live customer data — hand over exact instructions.
  if (rootDevice.startsWith("/dev/mapper/") || /^dm-\d+$/.test(parentName)) {
    return { error: "the root filesystem is on LVM" };
  }
  if (!DEV_NAME_RE.test(parentName)) {
    return { error: `could not identify the parent disk of ${rootDevice}` };
  }
  if (!PARTNUM_RE.test(partNum)) {
    return { error: `could not identify the partition number of ${rootDevice}` };
  }
  return { rootDevice, fsType, parentName, partNum };
}

/** The exact commands a customer (or support) can run to finish the job by hand. */
function manualCommands(layout: GuestLayout | null): string {
  if (layout) {
    return [
      `growpart /dev/${layout.parentName} ${layout.partNum}`,
      layout.fsType === "xfs"
        ? "xfs_growfs /"
        : layout.fsType === "btrfs"
          ? "btrfs filesystem resize max /"
          : `resize2fs ${layout.rootDevice}`,
    ].join(" && ");
  }
  return (
    "ROOT=$(findmnt -nro SOURCE /); PARENT=/dev/$(lsblk -nro PKNAME \"$ROOT\"); " +
    "PART=$(cat /sys/class/block/$(basename \"$ROOT\")/partition); " +
    "growpart \"$PARENT\" \"$PART\" && (resize2fs \"$ROOT\" || xfs_growfs /)"
  );
}

/**
 * Grow the guest filesystem online. Returns null on success, or a human-readable
 * reason plus the exact remediation commands when it could not be done.
 */
async function growGuestFilesystem(
  server: any,
  onStep: (pct: number, step: string) => Promise<void>,
): Promise<{ reason: string; commands: string } | null> {
  let layout: GuestLayout | null = null;
  try {
    return await withServerSsh(server, async (conn) => {
      await onStep(62, "Detecting the root filesystem");
      const detected = await detectLayout(conn);
      if ("error" in detected) {
        return { reason: detected.error, commands: manualCommands(null) };
      }
      layout = detected;
      const parentPath = `/dev/${layout.parentName}`;
      if (!DEV_PATH_RE.test(parentPath)) {
        return { reason: "could not identify the parent disk", commands: manualCommands(null) };
      }

      // growpart ships in cloud-guest-utils (Debian/Ubuntu) or cloud-utils-growpart
      // (RHEL family). Fixed string — no interpolation.
      await onStep(70, "Preparing the guest tools");
      const ensure = await exec(
        conn,
        "if ! command -v growpart >/dev/null 2>&1; then " +
          "(DEBIAN_FRONTEND=noninteractive apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y cloud-guest-utils) || " +
          "dnf install -y cloud-utils-growpart || yum install -y cloud-utils-growpart || true; fi; " +
          "command -v growpart >/dev/null 2>&1 && echo OK || echo MISSING",
        SETUP_TIMEOUT_MS * 5,
      );
      if (!/\bOK\b/.test(ensure.stdout)) {
        return {
          reason: "growpart could not be installed on the server",
          commands: `apt-get install -y cloud-guest-utils || dnf install -y cloud-utils-growpart; ${manualCommands(layout)}`,
        };
      }

      // Make the kernel notice the larger block device before growing anything.
      // Every interpolated value passed the allowlist above and is quoted anyway.
      await onStep(78, "Rescanning the virtual disk");
      await exec(
        conn,
        `echo 1 > /sys/class/block/${shellQuote(layout.parentName)}/device/rescan 2>/dev/null; ` +
          `partprobe ${shellQuote(parentPath)} >/dev/null 2>&1; ` +
          `udevadm settle >/dev/null 2>&1; true`,
        QUICK_TIMEOUT_MS,
      );

      // growpart exits 1 with "NOCHANGE" when the partition is already maximal —
      // that is the idempotent-retry case, not a failure.
      await onStep(85, "Growing the root partition");
      const grow = await exec(
        conn,
        `growpart ${shellQuote(parentPath)} ${shellQuote(layout.partNum)} 2>&1`,
        SETUP_TIMEOUT_MS,
      );
      const growOut = `${grow.stdout}${grow.stderr}`;
      if (grow.code !== 0 && !/NOCHANGE/i.test(growOut)) {
        return {
          reason: `growpart failed: ${growOut.trim().slice(0, 200)}`,
          commands: manualCommands(layout),
        };
      }

      await onStep(92, "Growing the filesystem");
      const fsCmd =
        layout.fsType === "xfs"
          ? "xfs_growfs / 2>&1"
          : layout.fsType === "btrfs"
            ? "btrfs filesystem resize max / 2>&1"
            : `resize2fs ${shellQuote(layout.rootDevice)} 2>&1`;
      const fs = await exec(conn, fsCmd, SETUP_TIMEOUT_MS * 3);
      const fsOut = `${fs.stdout}${fs.stderr}`;
      // "Nothing to do" / "already N blocks long" are the no-op retry cases.
      if (fs.code !== 0 && !/nothing to do|already .* long|no change/i.test(fsOut)) {
        return {
          reason: `${layout.fsType} grow failed: ${fsOut.trim().slice(0, 200)}`,
          commands: manualCommands(layout),
        };
      }
      return null;
    });
  } catch (e: any) {
    // Unreachable / no credentials / timeout — the disk is still bigger.
    return {
      reason: String(e?.message ?? e).slice(0, 200),
      commands: manualCommands(layout),
    };
  }
}

export async function diskExpand(job: Job): Promise<void> {
  const payload = (job.payload ?? {}) as { addGB?: number; targetExtraDiskGB?: number };
  const addGB = Math.round(Number(payload.addGB ?? 0));
  if (!Number.isInteger(addGB) || addGB <= 0) throw new Error("disk expand: invalid addGB");

  const server = await db.server.findUnique({
    where: { id: job.serverId! },
    include: { plan: true, node: true, dedicatedIp: true },
  });
  if (!server) throw new Error(`Server ${job.serverId} not found`);

  // Target is recorded on the job at purchase time so a concurrent write can't
  // move the goalposts; fall back to "current + addGB" for older payloads.
  const targetExtraDiskGB = Math.max(
    server.extraDiskGB,
    Math.round(Number(payload.targetExtraDiskGB ?? server.extraDiskGB + addGB)),
  );
  const targetTotalGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
  const link = `/dashboard/servers/${server.id}`;
  const step = (pct: number, s: string) => reportJobProgress(job.id, pct, s);

  if (SANDBOX) {
    // Simulate the whole sequence — no Proxmox call, no SSH — but exercise the
    // real progress bar and persist the purchased storage so billing is exact.
    for (const s of [
      { pct: 8, step: "Checking current disk size" },
      { pct: 30, step: `Growing the virtual disk to ${targetTotalGB} GB` },
      { pct: 60, step: "Connecting to the server" },
      { pct: 85, step: "Growing the root partition" },
      { pct: 95, step: "Growing the filesystem" },
    ]) {
      await step(s.pct, s.step);
      await new Promise((r) => setTimeout(r, 400));
    }
    await db.server.update({ where: { id: server.id }, data: { extraDiskGB: targetExtraDiskGB } });
    await step(100, "Storage expanded");
    await notify(
      server.userId,
      `${server.hostname}: storage expanded to ${targetTotalGB} GB`,
      `Sandbox expansion of +${addGB} GB completed (no real VM was touched). Added storage is permanent.`,
      link,
    );
    return;
  }

  if (!server.vmid) throw new Error("disk expand: server has no VM yet");
  const { conn } = await nodeFor(server);

  // 1. What size is the disk RIGHT NOW? (Authoritative — survives retries.)
  await step(5, "Checking current disk size");
  const cfg = await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`);
  const currentGB = parseDiskSizeGB(cfg?.scsi0);
  if (currentGB == null) throw new Error("disk expand: could not read the current scsi0 disk size");

  // 2. Grow on the hypervisor — ONLY when it isn't already big enough. A retry
  //    after a crash lands here with the disk already grown and skips straight
  //    to the guest-side grow (idempotent, never shrinks).
  const deltaGB = targetTotalGB - currentGB;
  if (deltaGB > 0) {
    await step(15, `Growing the virtual disk to ${targetTotalGB} GB`);
    // Proxmox accepts only a POSITIVE delta here ("+NG") and refuses to shrink.
    const upid = await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
      disk: "scsi0",
      size: `+${deltaGB}G`,
    });
    if (typeof upid === "string" && upid.startsWith("UPID")) {
      await step(30, "Waiting for the hypervisor");
      await conn.waitForTask(upid, 600_000);
    }
  } else {
    console.log(`[disk-expand] vmid ${server.vmid} already ${currentGB}G >= ${targetTotalGB}G — skipping Proxmox resize`);
  }

  // 3. Grow the guest filesystem ONLINE. A failure here is NOT a job failure —
  //    the space is already paid for and already attached.
  let warn: { reason: string; commands: string } | null = null;
  if (server.status !== "RUNNING") {
    warn = {
      reason: "the server is powered off",
      commands: manualCommands(null),
    };
  } else {
    await step(55, "Connecting to the server");
    warn = await growGuestFilesystem(server, step);
  }

  // 4. Persist the purchased storage. Done AFTER the disk really grew, so a
  //    terminal failure before this point is refunded by the worker's reconcile
  //    pass and never renews.
  await db.server.update({ where: { id: server.id }, data: { extraDiskGB: targetExtraDiskGB } });

  if (warn) {
    await step(100, `Disk grown to ${targetTotalGB} GB — filesystem needs a manual grow`);
    await notify(
      server.userId,
      `${server.hostname}: disk grown to ${targetTotalGB} GB — one step left`,
      `We added ${addGB} GB and your virtual disk is now ${targetTotalGB} GB, but we couldn't expand the filesystem automatically because ${warn.reason}. ` +
        (server.status !== "RUNNING"
          ? "Most images grow the filesystem by themselves on the next boot — just start the server. If it doesn't, "
          : "") +
        `SSH in as root and run:\n\n    ${warn.commands}\n\nThen \`df -h /\` will show the full ${targetTotalGB} GB. Added storage is permanent for this server's lifetime.`,
      link,
    );
    console.warn(`[disk-expand] ${server.hostname}: online grow skipped — ${warn.reason}`);
    return;
  }

  await step(100, `Storage expanded to ${targetTotalGB} GB`);
  await notify(
    server.userId,
    `${server.hostname}: storage expanded to ${targetTotalGB} GB`,
    `We added ${addGB} GB to this server's disk and grew the filesystem — \`df -h /\` shows it now. Added storage is permanent for this server's lifetime and renews with the server.`,
    link,
  );
}
NXEOF
