          status: "PAID",
          period: { start: new Date(), end: addMonths(new Date(), term.months) },
          lineItems: [
            { description: `${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
          ],
        }),
      });
