"use client";

import { useState, useTransition } from "react";
import { expandServerDisk } from "@/lib/actions-disk";
import { fmtMoney } from "@/components/ui/primitives";
import { walletSplit } from "@/lib/wallet-split";
import {
  EXTRA_DISK_MIN_GB,
  EXTRA_DISK_ONE_WAY_NOTE,
  EXTRA_DISK_STEP_GB,
  effectiveDiskGB,
  extraDiskCentsAt,
  maxAddableExtraDiskGB,
} from "@/lib/extra-disk";

/** Average calendar month in ms — mirrors diskExpandQuote on the server (estimate only). */
const MS_PER_AVG_MONTH = 30.44 * 86400_000;

/**
 * Post-deploy "Add storage": grow THIS server's own disk without changing its
 * plan. Sits next to Resize, and is deliberately a separate control because the
 * two do different things — Resize changes CPU/RAM/price, this only adds disk.
 *
 * Money maths is identical to lib/actions-disk.ts expandServerDisk (proration ×
 * remaining term, then lib/wallet-split.ts), so what is shown here is what gets
 * charged; the server recomputes it authoritatively before taking a cent.
 *
 * GROWTH IS ONE-WAY — stated on the card, in the confirm dialog and in the
 * button copy. There is no shrink control because there is no shrink path.
 */
export function AddStorage({
  serverId,
  hostname,
  planDiskGB,
  extraDiskGB,
  pricePerGbCents,
  expiresAt,
  isFree,
  walletBalanceCents,
  disabled,
}: {
  serverId: string;
  hostname: string;
  planDiskGB: number;
  extraDiskGB: number;
  pricePerGbCents: number;
  /** ISO string of the current term end, or null (free/admin servers). */
  expiresAt: string | null;
  isFree: boolean;
  walletBalanceCents: number;
  disabled?: boolean;
}) {
  const maxAdd = maxAddableExtraDiskGB(planDiskGB, extraDiskGB);
  const [addGB, setAddGB] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  // Apply the wallet balance by default whenever there's something to apply.
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);

  const currentTotal = effectiveDiskGB(planDiskGB, extraDiskGB);
  const newTotal = currentTotal + addGB;
  const monthlyCents = extraDiskCentsAt(addGB, pricePerGbCents);

  // Estimated prorated charge (mirrors diskExpandQuote on the server). The server
  // recomputes authoritatively; this only drives the copy + button.
  const prorate =
    isFree || !expiresAt
      ? 0
      : Math.max(
          0,
          Math.round(
            monthlyCents *
              Math.max(0, (new Date(expiresAt).getTime() - Date.now()) / MS_PER_AVG_MONTH),
          ),
        );

  // Exact wallet/card split — identical math to the server action, so the numbers
  // shown here are what actually gets charged.
  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
  const { walletApplied, cardCents } = split;

  return (
    <div className="card">
      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
        <h2 className="font-semibold">Add storage</h2>
        <span className="text-xs text-slate-400">
          {fmtMoney(pricePerGbCents)}/GB/mo
        </span>
      </div>
      <p className="mb-4 text-sm text-slate-400">
        Grow this server&apos;s own disk without changing its plan — CPU, RAM and the plan price stay
        exactly as they are. Currently{" "}
        <span className="font-semibold text-slate-200">{currentTotal} GB</span>
        {extraDiskGB > 0 && (
          <span className="text-slate-500">
            {" "}
            ({planDiskGB} GB plan + {extraDiskGB} GB added)
          </span>
        )}
        .
      </p>

      {error && (
        <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      {maxAdd <= 0 ? (
        <p className="text-sm text-slate-400">
          This server is at the maximum disk size. Attach a block-storage volume for more space —
          volumes stay portable and can be detached later.
        </p>
      ) : (
        <>
          <div className="flex items-center gap-3">
            <input
              type="range"
              className="flex-1 accent-brand-400"
              min={0}
              max={maxAdd}
              step={EXTRA_DISK_STEP_GB}
              value={addGB}
              aria-label="Storage to add in GB"
              disabled={pending || disabled}
              onChange={(e) => setAddGB(Number(e.target.value))}
            />
            <div className="flex shrink-0 gap-1.5">
              {[10, 50, 100, 250].filter((g) => g <= maxAdd).map((g) => (
                <button
                  type="button"
