          <div className="mt-4 space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
            {addGB > 0 && prorate > 0 && walletBalanceCents > 0 && (
              <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
                <span className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={useWallet}
                    onChange={(e) => setUseWallet(e.target.checked)}
                  />
                  Apply my balance ({fmtMoney(walletBalanceCents)})
                </span>
                <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
              </label>
            )}
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p className="text-xs text-slate-400">
                {addGB > 0 ? (
                  <>
                    Disk grows to <span className="font-semibold text-slate-200">{newTotal} GB</span>{" "}
                    and adds <span className="font-semibold">{fmtMoney(monthlyCents)}/mo</span> to every
                    renewal.
                    {prorate > 0 ? (
                      <>
                        {" "}
                        Due now: <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest
                        of your term
                        {walletApplied > 0 && (
                          <>
                            {" "}
                            — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span>{" "}
                            from your wallet
                          </>
                        )}
                        {cardCents > 0 ? (
                          <>
                            {" "}
                            and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card
                            checkout
                          </>
                        ) : (
                          <> (nothing due on card)</>
                        )}
                        .
                        {split.clampedForStripeMin && (
                          <>
                            {" "}
                            Card payments have a {fmtMoney(50)} minimum, so {fmtMoney(cardCents)} goes on
                            the card.
                          </>
                        )}
                      </>
                    ) : (
                      <> Nothing due now.</>
                    )}{" "}
                    No reboot needed — we grow the filesystem live.
                  </>
                ) : (
                  "Choose how much storage to add. No reboot needed — we grow the disk and filesystem live."
                )}
              </p>
              <button
                className="btn-primary"
                disabled={addGB <= 0 || pending || disabled}
                onClick={() => {
                  if (addGB <= 0) return;
                  if (
                    !window.confirm(
                      `Add ${addGB} GB to ${hostname}, taking its disk to ${newTotal} GB?\n\n` +
                        `This is PERMANENT — storage can be added but never removed, and it adds ` +
                        `${fmtMoney(monthlyCents)}/mo to every renewal for the life of this server.` +
                        (prorate > 0 ? `\n\nDue now: ${fmtMoney(prorate)} for the rest of your term.` : ""),
                    )
                  )
                    return;
                  start(async () => {
                    setError(null);
                    const res = await expandServerDisk(serverId, addGB, useWallet);
                    // Card portion > 0 → the action returns a Stripe Checkout URL.
                    if (res?.checkoutUrl) {
                      window.location.href = res.checkoutUrl;
                      return;
                    }
                    if (res?.error) setError(res.error);
                    else setAddGB(0);
                  });
                }}
              >
                {pending
                  ? "Adding storage…"
                  : addGB <= 0
                    ? "Choose an amount"
                    : cardCents > 0
                      ? `Continue to payment — ${fmtMoney(cardCents)}`
                      : prorate > 0
                        ? `Add ${addGB} GB permanently — ${fmtMoney(walletApplied)}`
                        : `Add ${addGB} GB permanently`}
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
