export function RenewalCard({
  serverId,
  autoRenew,
  expiresAt,
  priceCents,
  suspendedUnpaid,
}: {
  serverId: string;
  autoRenew: boolean;
  expiresAt: string | null;
  priceCents: number;
  suspendedUnpaid: boolean;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);

  return (
    <div className="card">
      <h2 className="mb-3 font-semibold">Subscription</h2>
      {error && (
        <div className="mb-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}
      <dl className="space-y-2 text-sm">
        <div className="flex justify-between">
          <dt className="text-slate-400">Price</dt>
          <dd>${(priceCents / 100).toFixed(2)}/mo</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">Paid until</dt>
          <dd>{expiresAt ? expiresAt.slice(0, 10) : "—"}</dd>
        </div>
        <div className="flex items-center justify-between">
          <dt className="text-slate-400">Auto-renew</dt>
          <dd>
            <button
              className={autoRenew ? "btn-secondary py-1" : "btn-primary py-1"}
              disabled={pending}
              onClick={() => start(() => toggleAutoRenew(serverId))}
            >
              {autoRenew ? "On — turn off" : "Off — turn on"}
            </button>
          </dd>
        </div>
      </dl>
      <button
        className="btn-primary mt-4 w-full"
        disabled={pending}
        onClick={() =>
          start(async () => {
            setError(null);
            const res = await renewNow(serverId);
            if (res?.error) setError(res.error);
          })
        }
      >
        {pending
          ? "Working…"
          : suspendedUnpaid
            ? `Pay $${(priceCents / 100).toFixed(2)} & restore server`
            : `Renew now (+30 days, $${(priceCents / 100).toFixed(2)})`}
      </button>
    </div>
  );
}

export function ExtendForm({ serverId }: { serverId: string }) {
  const [state, action, pending] = useActionState(adminExtendServer, {});
  return (
    <form action={action} className="flex items-center gap-2">
      <input type="hidden" name="serverId" value={serverId} />
      <input className="input w-20 py-1" name="days" type="number" placeholder="±days" />
      <button className="btn-secondary py-1" disabled={pending}>
        Extend
      </button>
      {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
    </form>
  );
}

